-- Expand the Steady-owned UK ingredient cost seed to every priced, non-alcohol grocery row
-- in the ONS September 2026 Shopping prices comparison tool workbook.
-- One ONS milk-delivery row has no published average price and is omitted.
on conflict (ingredient_key) do update set display_name=excluded.display_name, category=excluded.category;

on conflict (ingredient_key,market_country_code,currency_code,effective_month) do update set
  reference_amount=excluded.reference_amount, reference_unit=excluded.reference_unit, estimated_cost=excluded.estimated_cost,
  source_name=excluded.source_name, source_item=excluded.source_item, source_package_size=excluded.source_package_size,
  source_pack_price=excluded.source_pack_price, source_url=excluded.source_url, source_licence=excluded.source_licence,
  source_attribution=excluded.source_attribution, estimate_method=excluded.estimate_method, estimate_note=excluded.estimate_note, is_active=true;
